/** Returns new image references without changing published content until the admin saves. */
export async function uploadImages(request, response) {
  if (!request.files?.length) return response.status(400).json({ error: { code: 'NO_IMAGES', message: 'Select at least one image.' } });
  const images = await request.app.locals.mediaStore.upload(request.files);
  response.status(201).json({ images });
}